def batch_publish(messages, config=None):
    config = config or {}
    sns = boto3.client('sns', region_name=config['region'])
    topic_arn = config['topic_arn']
    publish_batch_request_entries = [
        {
            'Id': str(uuid.uuid4()),
            'Message': json.dumps(message),
            'MessageAttributes': {
                'MessageId': {
                    'StringValue': str(uuid.uuid4()),
                    'DataType': 'String'
                }
            }
        } for message in messages
    ]
    response = sns.publish_batch(
        TopicArn=topic_arn,
        PublishBatchRequestEntries=publish_batch_request_entries
    )
    return response['Successful'] + response['Failed']

import boto3


def get_messaging_client(service, region, credentials):
    session = boto3.Session(
        aws_access_key_id=credentials['access_key'],
        aws_secret_access_key=credentials['secret_key'],
        region_name=region
    )
    if service == 'sns':
        return session.client('sns')
    elif service == 'sqs':
        return session.client('sqs')
    else:
        raise ValueError('Unsupported service')

import json


def normalize_payload(payload):
    return json.dumps(payload)


def parse_response(response):
    return json.loads(response['Body']) if 'Body' in response else response

import boto3


def summarize_message_processing(messages, config=None):
    config = config or {}
    dynamodb = boto3.resource('dynamodb', region_name=config['region'])
    table = dynamodb.Table(config['table_name'])
    summary = {
        'total_messages': len(messages),
        'successful_messages': sum(1 for message in messages if message['status'] == 'SUCCESS'),
        'failed_messages': sum(1 for message in messages if message['status'] == 'FAILURE')
    }
    table.put_item(Item=summary)
    return summary

import boto3


def check_message_safety(message, config=None):
    config = config or {}
    comprehend = boto3.client('comprehend', region_name=config['region'])
    response = comprehend.detect_sentiment(
        Text=message['text'],
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    return sentiment!= 'NEGATIVE'
